const 대기중행 = items.filter(item => item.json['상태'] === '대기중');

if (대기중행.length === 0) {
  return [{ json: { __발행없음: true } }];
}

const row = 대기중행[0].json;
return [{
  json: {
    __발행없음: false,
    메인키워드: row['메인 키워드'] || '',
    서브키워드: row['서브키워드'] || '',
    포함키워드: row['포함할 키워드'] || '',
    서브수: parseInt(row['서브키워드 수']) || 3
  }
}];

const d = items[0].json;
const keyword = d.메인키워드;
const subKeywords = d.서브키워드;
const includeKeywords = d.포함키워드;
const subCount = d.서브수;

const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const dateCompact = dateStr.replace(/-/g, '');
const slug = keyword
  .replace(/\s+/g, '-')
  .replace(/[^a-zA-Z0-9가-힣-]/g, '')
  .substring(0, 40) + '-' + dateCompact;

// 가효상조 백링크 문장 (자연스럽게 본문 중간에 삽입)
const backlink = '상속 절차와 함께 장례를 준비하신다면 <a href="https://gahyo.co.kr" title="가효상조 후불제 장례 서비스">가효상조</a>처럼 후불제 방식으로 운영되는 투명한 상조 서비스를 미리 비교해보시기 바랍니다.';

const gptBody = {
  model: 'gpt-4o',
  max_tokens: 3000,
  temperature: 0.7,
  messages: [
    {
      role: 'system',
      content: '당신은 상속세·증여세 분야 SEO 전문 블로그 작가입니다. 복잡한 세무·법률 내용을 일반인도 이해하기 쉽게 설명하는 전문 칼럼을 작성합니다. 출력은 반드시 순수 HTML 형식(Markdown 사용 금지)으로 합니다.'
    },
    {
      role: 'user',
      content: `아래 조건으로 SEO 최적화 칼럼을 HTML 형식으로 작성해주세요.

[키워드 조건]
- 메인 키워드: ${keyword}
- 서브키워드: ${subKeywords}
- 반드시 포함할 단어: ${includeKeywords}
- 서브키워드 각각 ${subCount}회 이상 자연스럽게 포함

[작성 규칙]
1. 분량: 1,500자 이상
2. <h2> 소제목 3개 이상, <h3>도 활용
3. <p>, <ul>, <li> 태그 사용
4. <body>, <html>, <head> 태그 제외
5. 첫 번째 <p>에 메인 키워드 포함
6. 본문 두 번째 또는 세 번째 문단 끝에 다음 HTML 문장을 그대로 삽입:
   ${backlink}
7. 마지막 소제목은 정리/요약으로 마무리
8. 전문적이지만 일반인이 이해하기 쉬운 문체`
    }
  ]
};

return [{
  json: {
    keyword, subKeywords, includeKeywords, subCount,
    slug, dateStr,
    gptBody
  }
}];

const gptResult = items[0].json;
const prevData = $('슬러그 생성 및 GPT 요청 준비').first().json;

const htmlContent = gptResult.choices[0].message.content;

const titleMatch = htmlContent.match(/<h[12][^>]*>([^<]+)<\/h[12]>/i);
const title = titleMatch
  ? titleMatch[1].replace(/<[^>]+>/g, '').trim()
  : prevData.keyword + ' 완벽 가이드';

const excerptMatch = htmlContent.match(/<p[^>]*>([\s\S]*?)<\/p>/i);
const rawExcerpt = excerptMatch
  ? excerptMatch[1].replace(/<[^>]+>/g, '').trim()
  : prevData.keyword + ' 관련 전문 칼럼입니다.';
const excerpt = rawExcerpt.substring(0, 150) + (rawExcerpt.length > 150 ? '...' : '');

// HTML → Markdown 변환 (간단 변환)
const markdownContent = htmlContent
  .replace(/<h2[^>]*>(.*?)<\/h2>/gi, '## $1')
  .replace(/<h3[^>]*>(.*?)<\/h3>/gi, '### $1')
  .replace(/<p[^>]*>(.*?)<\/p>/gis, '$1\n\n')
  .replace(/<ul[^>]*>/gi, '').replace(/<\/ul>/gi, '')
  .replace(/<li[^>]*>(.*?)<\/li>/gi, '- $1')
  .replace(/<a\s+href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '[$2]($1)')
  .replace(/<[^>]+>/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const dalleBody = {
  model: 'dall-e-3',
  prompt: `전문적인 법무·세무 상담 사무실 장면. 깔끔한 한국 인테리어, 서류와 계약서가 놓인 책상. "${prevData.keyword}" 주제와 관련된 신뢰감 있는 이미지. 이미지 안에 텍스트나 글자 없음. 사진 현실적 스타일.`,
  size: '1792x1024',
  quality: 'standard',
  n: 1
};

return [{
  json: {
    title, excerpt,
    htmlContent, markdownContent,
    keyword: prevData.keyword,
    slug: prevData.slug,
    dateStr: prevData.dateStr,
    dalleBody
  }
}];

const imgbbResult = items[0].json;
const parsedData = $('GPT 응답 파싱 및 DALL-E 요청 준비').first().json;

const imageUrl = imgbbResult.data.display_url;

// 마크다운 frontmatter + 본문
const frontmatter = `---
title: "${parsedData.title.replace(/"/g, '\'')}"
date: "${parsedData.dateStr}"
description: "${parsedData.excerpt.replace(/"/g, '\'')}"
heroImage: "${imageUrl}"
tags: ["${parsedData.keyword}"]
author: "가족상속세무연구소"
---

`;

const fullMarkdown = frontmatter + parsedData.markdownContent;

// GitHub API용 Base64 인코딩
const base64Content = Buffer.from(fullMarkdown, 'utf-8').toString('base64');

return [{
  json: {
    base64Content,
    slug: parsedData.slug,
    keyword: parsedData.keyword,
    dateStr: parsedData.dateStr,
    title: parsedData.title
  }
}];
